class Solution:
    def sortVowelsByFrequency(self, s: str) -> str:
        vowels = set('aeiou')
        freq = {}
        pos = []
        chars = list(s)
        for i, ch in enumerate(chars):
            if ch in vowels:
                pos.append(i)
                freq[ch] = freq.get(ch, 0) + 1
        first = {}
        for i, ch in enumerate(chars):
            if ch in vowels and ch not in first:
                first[ch] = i
        order = sorted(freq.keys(), key=lambda c: (-freq[c], first[c]))
        seq = []
        for c in order:
            seq.extend([c] * freq[c])
        for idx, c in zip(pos, seq):
            chars[idx] = c
        return ''.join(chars)

