class Solution {
public:
    string sortVowelsByFrequency(string s) {
        string vows = "aeiou";
        unordered_map<char,int> freq, first;
        vector<int> pos;
        for (int i = 0; i < (int)s.size(); i++) {
            if (vows.find(s[i]) != string::npos) {
                pos.push_back(i);
                if (!first.count(s[i])) first[s[i]] = i;
                freq[s[i]]++;
            }
        }
        vector<pair<pair<int,int>,char>> v;
        for (auto& [c, f] : freq) v.push_back({{-f, first[c]}, c});
        stable_sort(v.begin(), v.end());
        string seq;
        for (auto& p : v) seq.append(string(-p.first.first, p.second));
        int k = 0;
        for (int i : pos) s[i] = seq[k++];
        return s;
    }
};

