class Solution {
    public String sortVowelsByFrequency(String s) {
        Set<Character> vw = Set.of('a','e','i','o','u');
        Map<Character,Integer> freq = new HashMap<>(), first = new HashMap<>();
        List<Integer> pos = new ArrayList<>();
        char[] cs = s.toCharArray();
        for (int i = 0; i < cs.length; i++) {
            if (vw.contains(cs[i])) {
                pos.add(i);
                first.putIfAbsent(cs[i], i);
                freq.merge(cs[i], 1, Integer::sum);
            }
        }
        List<Character> keys = new ArrayList<>(freq.keySet());
        keys.sort((a, b) -> {
            int d = freq.get(b) - freq.get(a);
            return d != 0 ? d : first.get(a) - first.get(b);
        });
        StringBuilder sb = new StringBuilder();
        for (char c : keys) for (int i = 0; i < freq.get(c); i++) sb.append(c);
        int k = 0;
        for (int i : pos) cs[i] = sb.charAt(k++);
        return new String(cs);
    }
}

