class Solution:
    def sortVowelsByFrequency(self, s: str) -> str:
        vowels = 'aeiou'
        freq = {c: 0 for c in vowels}
        first = {}
        pos = []
        chars = list(s)
        for i, ch in enumerate(chars):
            if ch in freq:
                pos.append(i)
                freq[ch] += 1
                first.setdefault(ch, i)
        seq = []
        remaining = sum(freq.values())
        while remaining:
            c = max(vowels, key=lambda v: (freq[v], -first.get(v, 10**9)))
            seq.append(c)
            freq[c] -= 1
            remaining -= 1
        for p, c in zip(pos, seq):
            chars[p] = c
        return ''.join(chars)

