class Solution {
public:
    string sortVowelsByFrequency(string s) {
        string vows = "aeiou";
        int freq[26] = {0}, first[26];
        fill(begin(first), end(first), INT_MAX);
        vector<int> pos;
        for (int i = 0; i < (int)s.size(); i++) {
            if (vows.find(s[i]) != string::npos) {
                pos.push_back(i);
                freq[s[i]-'a']++;
                first[s[i]-'a'] = min(first[s[i]-'a'], i);
            }
        }
        string seq;
        int remaining = pos.size();
        while (remaining--) {
            int best = -1;
            for (char c : vows) {
                int id = c - 'a';
                if (freq[id] > 0 && (best == -1 ||
                    freq[id] > freq[best] ||
                    (freq[id] == freq[best] && first[id] < first[best])))
                    best = id;
            }
            seq += char('a' + best);
            freq[best]--;
        }
        for (int k = 0; k < (int)pos.size(); k++) s[pos[k]] = seq[k];
        return s;
    }
};

