                freq[cs[i]-'a']++;
                first[cs[i]-'a'] = Math.min(first[cs[i]-'a'], i);
            }
        }
        StringBuilder seq = new StringBuilder();
        for (int rem = pos.size(); rem > 0; rem--) {
            int best = -1;
            for (char c : vows.toCharArray()) {
                int id = c - 'a';
                if (freq[id] > 0 && (best == -1 ||
                    freq[id] > freq[best] ||
                    (freq[id] == freq[best] && first[id] < first[best])))
